{$ param gap_class label="Gap Class" default="gap-8" description="Tailwind gap utility between columns." $}

<div class="grid grid-cols-1 md:grid-cols-3 {$= gap_class $} mb-8">
  <div>
    {$ slot col_1 $}
      <p class="ss-text">Column 1.</p>
    {$ /slot $}
  </div>
  <div>
    {$ slot col_2 $}
      <p class="ss-text">Column 2.</p>
    {$ /slot $}
  </div>
  <div>
    {$ slot col_3 $}
      <p class="ss-text">Column 3.</p>
    {$ /slot $}
  </div>
</div>
